import "server-only";
import { google } from "googleapis";
import { getTokensForUser, saveTokensForUser } from "./token-store";

if (!process.env.GOOGLE_CLIENT_ID) {
  throw new Error("GOOGLE_CLIENT_ID is missing from .env.local");
}
if (!process.env.GOOGLE_CLIENT_SECRET) {
  throw new Error("GOOGLE_CLIENT_SECRET is missing from .env.local");
}
if (!process.env.GOOGLE_REDIRECT_URI) {
  throw new Error("GOOGLE_REDIRECT_URI is missing from .env.local");
}

export async function createCalendarClient(userId: string) {
  const tokens = await getTokensForUser(userId);
  if (!tokens) {
    throw new Error(
      `No Google Calendar tokens found for user "${userId}". Direct the user to connect their Google account first.`,
    );
  }

  const oauth2Client = new google.auth.OAuth2(
    process.env.GOOGLE_CLIENT_ID,
    process.env.GOOGLE_CLIENT_SECRET,
    process.env.GOOGLE_REDIRECT_URI,
  );

  oauth2Client.setCredentials({
    access_token: tokens.accessToken,
    refresh_token: tokens.refreshToken,
    expiry_date: tokens.expiresAt,
  });

  // Persist refreshed tokens so the next request doesn't refresh again.
  //
  // RACE CONDITION (accepted): Two concurrent calls for the same user each
  // construct their own OAuth2 client, both refresh against Google, both fire
  // this event. Last-write-wins. This is acceptable because:
  //   1. Google's refresh tokens are stable (only re-issued on first consent).
  //   2. Two access tokens issued seconds apart are both valid.
  //   3. The newer access token always overwrites the older one below via the
  //      `expiry_date` comparison, so we never persist a stale token over a
  //      fresh one in the common case.
  // If you need stronger guarantees (e.g. a per-user mutex), add the lock in
  // your adapter's `saveTokens` implementation.
  oauth2Client.on("tokens", async (newTokens) => {
    const newExpiry = newTokens.expiry_date ?? Date.now() + 3_600_000;
    // Refuse to overwrite a newer token with a stale one. Re-read first so two
    // concurrent saves converge on the latest token rather than ping-ponging.
    const current = await getTokensForUser(userId);
    if (current && current.expiresAt > newExpiry) return;
    await saveTokensForUser(userId, {
      accessToken: newTokens.access_token ?? tokens.accessToken,
      // Google only re-issues the refresh token on first consent; keep the
      // existing one if the refresh response doesn't include a new one.
      refreshToken: newTokens.refresh_token ?? tokens.refreshToken,
      expiresAt: newExpiry,
    });
  });

  return google.calendar({ version: "v3", auth: oauth2Client });
}

