"use server";
import "server-only";

import crypto from "crypto";
import { google } from "googleapis";
import { saveTokensForUser } from "./token-store";

const SCOPES = [
  "https://www.googleapis.com/auth/calendar",
  "https://www.googleapis.com/auth/calendar.events",
];

// Reject callbacks where the original auth URL was created more than 10 minutes ago.
// Tight enough to limit replay attacks; loose enough for a normal consent flow.
const STATE_MAX_AGE_MS = 10 * 60 * 1000;

function createOAuthClient() {
  return new google.auth.OAuth2(
    process.env.GOOGLE_CLIENT_ID,
    process.env.GOOGLE_CLIENT_SECRET,
    process.env.GOOGLE_REDIRECT_URI,
  );
}

/**
 * Build an HMAC-signed state token: `<base64url(payload)>.<hmac>`.
 * Prevents CSRF: an attacker can't forge a valid state for an arbitrary userId
 * because they don't have GOOGLE_CLIENT_SECRET.
 */
function signState(userId: string): string {
  if (!process.env.GOOGLE_CLIENT_SECRET) {
    throw new Error("GOOGLE_CLIENT_SECRET is required to sign OAuth state.");
  }
  const payload = JSON.stringify({
    userId,
    nonce: crypto.randomBytes(16).toString("base64url"),
    iat: Date.now(),
  });
  const encoded = Buffer.from(payload).toString("base64url");
  const hmac = crypto
    .createHmac("sha256", process.env.GOOGLE_CLIENT_SECRET)
    .update(encoded)
    .digest("base64url");
  return `${encoded}.${hmac}`;
}

/**
 * Verify the HMAC, age, and return the userId. Returns null on any failure —
 * forged state, tampered userId, expired state.
 */
function verifyState(state: string): string | null {
  if (!process.env.GOOGLE_CLIENT_SECRET) return null;
  const [encoded, signature] = state.split(".");
  if (!encoded || !signature) return null;

  const expected = crypto
    .createHmac("sha256", process.env.GOOGLE_CLIENT_SECRET)
    .update(encoded)
    .digest("base64url");

  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(signature, "utf8");
  if (a.length !== b.length) return null;
  if (!crypto.timingSafeEqual(a, b)) return null;

  let parsed: { userId?: unknown; iat?: unknown };
  try {
    parsed = JSON.parse(Buffer.from(encoded, "base64url").toString("utf-8"));
  } catch {
    return null;
  }
  if (typeof parsed.userId !== "string" || typeof parsed.iat !== "number") {
    return null;
  }
  if (Date.now() - parsed.iat > STATE_MAX_AGE_MS) return null;
  return parsed.userId;
}

/**
 * Returns the Google OAuth URL to redirect the user to.
 * Call this from a Server Action triggered by a "Connect Google Calendar" button.
 * `userId` MUST come from the current authenticated session, not user input.
 */
export async function getAuthorizationUrl(userId: string): Promise<string> {
  const oauth2Client = createOAuthClient();
  // `prompt: "consent"` forces Google to issue a refresh_token on every auth.
  // Without it, refresh tokens are only issued on first consent and are lost
  // if the user revokes and re-connects.
  return oauth2Client.generateAuthUrl({
    access_type: "offline",
    scope: SCOPES,
    prompt: "consent",
    state: signState(userId),
  });
}

/**
 * Exchanges the OAuth callback code for tokens and persists them.
 * Pass `currentSessionUserId` from your auth system — if it doesn't match the
 * userId in the signed state, this is a CSRF/account-link attack and we abort.
 */
export async function handleOAuthCallback(
  code: string,
  state: string,
  currentSessionUserId: string,
): Promise<void> {
  const stateUserId = verifyState(state);
  if (!stateUserId) {
    throw new Error("Invalid or expired OAuth state.");
  }
  // Defense in depth: the HMAC alone prevents state forgery, but this also
  // catches the case where a user starts the flow while logged in as A and
  // completes it while logged in as B (account confusion).
  if (stateUserId !== currentSessionUserId) {
    throw new Error(
      "OAuth state does not match the current session — possible CSRF attempt.",
    );
  }

  const oauth2Client = createOAuthClient();
  const { tokens } = await oauth2Client.getToken(code);

  if (!tokens.access_token) {
    throw new Error("Google OAuth did not return an access token.");
  }
  if (!tokens.refresh_token) {
    throw new Error(
      "Google OAuth did not return a refresh token. " +
        "Ensure the authorization URL uses access_type=offline and prompt=consent.",
    );
  }

  await saveTokensForUser(stateUserId, {
    accessToken: tokens.access_token,
    refreshToken: tokens.refresh_token,
    expiresAt: tokens.expiry_date ?? Date.now() + 3_600_000,
  });
}

